import  sys 
import  json 
try : 
data = json.loads(sys.stdin.read()) 
original_cmd = data.get( "tool_input" , {}).get( "command" ,  "" ) 
prefix = ( 
"chcp.com 65001 > /dev/null 2>&1; " 
"export LANG=zh_CN.UTF-8; " 
"export LC_ALL=zh_CN.UTF-8; " 
"export PYTHONUTF8=1; " 
"export PYTHONIOENCODING=utf-8; " 
"export LESSCHARSET=utf-8; " 
) 
sys.stdout.write(json.dumps({ 
"hookSpecificOutput" : { 
"hookEventName" :  "PreToolUse" , 
"permissionDecision" :  "allow" , 
"updatedInput" : { 
"command" : prefix + original_cmd 
} 
} 
})) 
except  Exception: 
pass 
sys.exit( 0 )

{ 
"hooks" : { 
"PreToolUse" : [ 
{ 
"matcher" : "Bash" , 
"hooks" : [ 
{ 
"type" : "command" , 
"command" : "python scripts/hooks/pre-bash-utf8.py" 
} 
] 
} 
] 
} 
}

# ---- 3. Deploy shim exe (node.exe + cli.mjs) ---- 
$nodeDir        = "D:\DevEnvs 
ode" 
$shimExePath    = Join-Path $nodeDir "typescript-language-server.exe" 
$cliMjsPath     = Join-Path $nodeDir "node_modules\typescript-language-server\lib\cli.mjs" 
if ((Test-Path (Join-Path $nodeDir "node.exe")) -and (Test-Path $cliMjsPath)) { 
try { 
Install-ShimExe -TargetExePath $shimExePath ` 
-ShimTargetPath "$nodeDir 
ode.exe" ` 
-ShimArgs "$cliMjsPath" 
} 
catch { 
Write-Host "[WARN] Shim deployment failed (non-critical): $_" -ForegroundColor Yellow 
} 
}

